class Solution:
    def findSwapped(self, nodes: List[int]) -> List[int]:
        # Rebuild child links from the level order, then walk in order without recursion.
        val, left, right = [nodes[0]], [-1], [-1]
        q = deque([0]); i = 1
        while q and i < len(nodes):
            cur = q.popleft()
            for side in (left, right):
                if i < len(nodes) and nodes[i] != -1:
                    val.append(nodes[i]); left.append(-1); right.append(-1)
                    side[cur] = len(val) - 1; q.append(len(val) - 1)
                i += 1
        seq, st, c = [], [], 0
        while st or c != -1:
            while c != -1:
                st.append(c); c = left[c]
            c = st.pop(); seq.append(val[c]); c = right[c]
        first = last = -1
        for k in range(len(seq) - 1):
            if seq[k] > seq[k + 1]:
                if first == -1: first = k
                last = k + 1
        return sorted([seq[first], seq[last]])

