class Solution {
public:
    vector<int> findSwapped(vector<int>& nodes) {
        vector<int> val{nodes[0]}, L{-1}, R{-1};
        deque<int> q{0}; size_t i = 1;
        while (!q.empty() && i < nodes.size()) {
            int cur = q.front(); q.pop_front();
            for (int s = 0; s < 2; s++, i++) {
                if (i < nodes.size() && nodes[i] != -1) {
                    val.push_back(nodes[i]); L.push_back(-1); R.push_back(-1);
                    (s ? R : L)[cur] = val.size() - 1; q.push_back(val.size() - 1);
                }
            }
        }
        vector<int> seq, st; int c = 0;
        while (!st.empty() || c != -1) {
            while (c != -1) { st.push_back(c); c = L[c]; }
            c = st.back(); st.pop_back(); seq.push_back(val[c]); c = R[c];
        }
        int first = -1, last = -1;
        for (size_t k = 0; k + 1 < seq.size(); k++) if (seq[k] > seq[k + 1]) { if (first < 0) first = k; last = k + 1; }
        int a = seq[first], b = seq[last];
        return {min(a, b), max(a, b)};
    }
};

